<script setup lang="ts">
import { computed, ref, useId } from 'vue'
import { isTauri } from '@tauri-apps/api/core'
import AppIcon from './AppIcon.vue'
import ChoiceSelect from './ChoiceSelect.vue'
import ElementCandidate from './ElementCandidate.vue'
import { elementColor, symbols } from '../lib/model'
import { spectrumBrowser as state, loadReferences, loadNistReferences, cancelReferences, clearReferences, addReferenceElement, toggleReferenceElement, toggleReferenceSpecies } from '../lib/spectrumBrowser'
const id=useId(),input=ref<HTMLInputElement>(),adding=ref(''),error=ref(''),nistExpanded=ref(false)
const availableSymbols=computed(()=>[...new Set(state.references.map(g=>g.element))].filter(e=>!state.addedElements.includes(e)))
const sourceGroups=computed(()=>state.references.filter(g=>state.addedElements.includes(g.element)))
const units=[{value:'nm',label:'nm'},{value:'angstrom',label:'Å（×0.1 → nm）'},{value:'um',label:'μm（×1000 → nm）'}]
const enabled=(element:string)=>state.references.some(g=>g.element===element&&state.selected.includes(g.id))
function add(){const symbol=availableSymbols.value.find(e=>e.toLowerCase()===adding.value.trim().toLowerCase());if(!symbol){error.value='请选择当前已加载库中的元素';return}addReferenceElement(symbol);adding.value='';error.value=''}
async function choose(){if(isTauri())await loadReferences(undefined,true);else input.value?.click()}
function file(event:Event){const target=event.target as HTMLInputElement,f=target.files?.[0];if(f)void loadReferences(f,true);target.value=''}
</script>
<template>
  <section class="panel reference-panel">
    <button type="button" class="reference-heading" :aria-expanded="state.referencesExpanded" :aria-controls="id" @click="state.referencesExpanded=!state.referencesExpanded"><h2>谱线位置参考</h2><span v-if="state.referencePending||state.nistPending">加载中…</span><span v-else-if="state.referenceError" class="reference-error">加载失败</span><span v-else-if="state.configuredLoaded" class="reference-success">本地库 · {{ state.configuredCount }} 位置</span><span v-else-if="state.references.length">参考组 · {{ state.references.length }}</span><AppIcon name="chevron" :size="14" :class="{expanded:state.referencesExpanded}" /></button>
    <div :id="id" v-show="state.referencesExpanded" class="reference-body">
      <div class="reference-actions"><div class="reference-entry-grid"><button type="button" :class="['btn',{'reference-loaded':state.configuredLoaded&&!state.referencePending}]" :disabled="state.referencePending||state.nistPending" @click="loadReferences()">{{ state.referencePending?'正在加载…':state.configuredLoaded?'已加载 · 刷新当前库':'加载当前谱线库' }}</button><button type="button" class="btn nist-button" :disabled="state.referencePending||state.nistPending" :aria-expanded="nistExpanded" :aria-controls="id+'-nist'" title="选择元素并从 NIST Handbook Persistent Lines 加载 I/II" @click="nistExpanded=!nistExpanded">加载 NIST 在线谱线库</button></div><div class="reference-secondary-actions"><button v-if="state.referencePending||state.nistPending" type="button" class="btn reference-cancel" @click="cancelReferences">取消</button><button v-if="state.references.length" type="button" class="icon-btn" title="清空参考库" aria-label="清空参考库" @click="clearReferences"><AppIcon name="close" :size="14" /></button></div></div>
      <p v-if="state.referenceError" class="error-text" role="alert">{{ state.referenceError }}<span v-if="state.references.length">；上次成功数据保留。</span></p>
      <div v-if="nistExpanded" :id="id+'-nist'" class="nist-online"><label :for="id+'-nist-element'">NIST 元素</label><ElementCandidate :id="id+'-nist-element'" v-model="state.nistElement" :symbols="symbols" :disabled="state.referencePending||state.nistPending" /><button type="button" class="btn sm nist-query" :disabled="state.referencePending||state.nistPending" @click="loadNistReferences(state.nistElement)">{{ state.nistPending?'正在加载 NIST…':'加载／刷新元素' }}</button><small>NIST Handbook Persistent Lines · 官方在线来源，仅查询所选元素 I/II。</small><small v-if="state.nistStatus" role="status">{{ state.nistStatus }}</small><small v-for="issue in state.nistIssues" :key="issue.file" class="error-text">{{ issue.file }}：{{ issue.error }}</small></div><form v-if="state.references.length" class="add-element" @submit.prevent="add"><ElementCandidate :id="id+'-element'" v-model="adding" :symbols="availableSymbols" :disabled="state.referencePending||state.nistPending" :issue="error" /><button type="submit" class="btn sm" :disabled="!availableSymbols.length">添加</button></form><p v-if="error" class="error-text" role="alert">{{ error }}</p>
      <div class="reference-elements"><div v-for="element in state.addedElements" :key="element" class="reference-element"><button type="button" :class="['element-tile',{'element-muted':!enabled(element)}]" :style="{'--el-color':elementColor(element)}" :aria-pressed="enabled(element)" :aria-label="(enabled(element)?'关闭':'启用')+'参考元素 '+element" :title="'点击启用／关闭 '+element" @click="toggleReferenceElement(element)">{{ element }}</button><div class="reference-species"><label v-for="group in state.references.filter(g=>g.element===element)" :key="group.id" :title="group.source"><input type="checkbox" :checked="state.selected.includes(group.id)" :aria-label="'参考 '+group.label" @change="toggleReferenceSpecies(group.id)" /><span>{{ group.species }}</span><small>{{ group.originKind==='nist'?'NIST':group.originKind==='user'?'CSV':'本地' }} · {{ group.count }}</small></label></div></div></div>
      <details v-for="group in sourceGroups.filter(g=>g.originKind==='nist')" :key="group.id" class="nist-originals"><summary>{{ group.label }} · 来源与原字段</summary><p class="hint">{{ group.source }}<br />获取时间：{{ group.metadata?.fetched_at }}<br />HTML SHA256：{{ group.sha256 }}<br />波长原值 Å，仅除以10转换为 nm，不推断空气/真空介质。</p><details v-for="position in group.positions" :key="position.wavelength_nm"><summary>{{ position.wavelength_angstrom }} Å · {{ position.wavelength_nm }} nm</summary><article v-for="(record,i) in position.records" :key="i"><dl v-for="row in record.states" :key="row.line"><dt>页面行</dt><dd>{{ row.line }}</dd><dt>Intensity</dt><dd>{{ row.intensity||'—' }}</dd><dt>Å 原值</dt><dd>{{ row.wavelength_angstrom||'（该行未重复列出）' }}</dd><dt>Aki</dt><dd>{{ row.aki||'—' }} {{ row.aki_unit }}</dd><dt>Energy</dt><dd>{{ row.energy||'—' }} {{ row.energy_unit }}</dd><dt>Configuration</dt><dd>{{ row.configuration||'—' }}</dd><dt>Term / J</dt><dd>{{ row.term||'—' }} / {{ row.j||'—' }}</dd><dt>Line Ref</dt><dd>{{ row.line_ref||'—' }}</dd><dt>Aki Ref</dt><dd>{{ row.aki_ref||'—' }}</dd></dl></article></details></details>
      <p v-if="state.spectrum?.unit==='pixel'" class="hint">pixel 轴不叠加 nm 参考。</p>
      <details><summary>用户参考 CSV／来源</summary><div class="row2"><label class="field">元素（可留空）<input v-model="state.userElement" placeholder="Fe" /></label><label class="field">species（可留空）<input v-model="state.userSpecies" placeholder="II" /></label></div><label class="field">波长列（从0开始）<input v-model="state.userColumn" inputmode="numeric" /></label><ChoiceSelect v-model="state.userUnit" label="参考波长原单位" :options="units" /><button type="button" class="btn sm" :disabled="state.referencePending" @click="choose">打开用户参考 CSV</button><input ref="input" type="file" accept=".csv" class="reference-file" aria-label="选择参考谱线CSV" @change="file" /><p class="hint">虚线仅位置，不是元素鉴定。悬停可读库原字段；无 Aki 的线仍显示。</p><p v-for="issue in state.referenceIssues" :key="issue.file" class="hint">{{ issue.file }}：{{ issue.error }}</p><div v-for="group in sourceGroups" :key="group.id" class="reference-source"><b>{{ group.label }}</b> · {{ group.source }} · {{ group.original_unit }} → nm<small>{{ group.unit_contract }}</small><small class="mono">SHA256 {{ group.sha256 }}</small></div></details>
    </div>
  </section>
</template>
<style scoped>
.reference-panel{padding:0;min-width:0}.reference-heading{width:100%;display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:17px 20px;border:0;border-radius:13px;background:transparent;color:var(--text);text-align:left}.reference-heading h2{margin:0;margin-right:auto}.reference-heading>span{font-size:11px;color:var(--muted)}.reference-heading>svg{transition:transform .18s}.reference-heading>svg.expanded{transform:rotate(90deg)}.reference-heading .reference-success{color:var(--good)}.reference-heading .reference-error{color:var(--bad)}.reference-body{padding:0 20px 18px}.reference-actions{display:flex;flex-direction:column;gap:8px;margin-bottom:14px}.reference-entry-grid{display:flex;gap:8px;min-width:0}.reference-entry-grid>.btn{flex:1 1 0;min-width:0;white-space:normal;line-height:1.35}.reference-secondary-actions{display:flex;gap:8px;min-height:36px}.reference-loaded{color:var(--good);border-color:color-mix(in srgb,var(--good) 40%,var(--border));background:color-mix(in srgb,var(--good) 7%,var(--panel))}.nist-button{color:var(--accent-text)}.nist-online{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}.nist-online .element-candidate{flex:1 1 120px}.nist-online small{flex-basis:100%;color:var(--muted);font-size:10px}.reference-elements{display:flex;flex-wrap:wrap;gap:14px;margin:15px 0}.reference-element{display:flex;align-items:flex-start;gap:8px}.reference-species{display:flex;gap:6px;flex-wrap:wrap;max-width:170px}.reference-species label{display:flex;gap:4px;align-items:center;font-size:12px}.reference-species small{color:var(--muted);font-size:10px}.element-muted{--el-color:var(--muted)!important;filter:grayscale(1);background:var(--panel-soft);border-color:var(--border)}.reference-file{display:none}details{font-size:12px}summary{cursor:pointer;color:var(--accent-text)}details .field{margin-top:10px}.reference-source{margin:10px 0;overflow-wrap:anywhere;font-size:11px}.reference-source small{display:block;color:var(--muted);font-size:10px}.hint{margin:10px 0}@media(max-width:740px){.reference-heading{padding:16px}.reference-body{padding:0 16px 16px}}
</style>
<style scoped>
.reference-species label{max-width:100%;overflow-wrap:anywhere}.nist-originals{overflow-wrap:anywhere}.nist-originals dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:3px 8px;font-size:11px}.nist-originals dd{margin:0}.nist-originals article{margin:10px 0;border-top:1px solid var(--border);padding-top:8px}
</style>
